mapper.insert:
insert into sys_admin (name, org_id, account, email, phone, sex, avatar, password, status, login_ip,login_date, remark) value
(#{name},#{orgId},#{account},#{email},#{phone},#{sex},#{avatar},#{password},#{status},#{loginIp},#{loginDate},#{remark});
set @lastId=LAST_INSERT_ID();

    insert into sys_admin_role (aid, rid) values

        (@lastId, #{item})

mapper.update:
update sys_admin set name=#{name},org_id=#{orgId},email=#{email},phone=#{phone}
     ,avatar=#{avatar},status=#{status},remark=#{remark} where id=#{id};
delete from sys_admin_role where aid=#{id};

    insert into sys_admin_role (aid, rid) values

        (#{id}, #{item})

mapper.delete:
delete from sys_admin where id in (

    #{item}
);
delete from sys_admin_role where aid in (

    #{item}

);

mapper.select:
select a.*, ar.aid aid, ar.rid rid from sys_admin a
   left join sys_admin_role ar on a.id = ar.aid
where a.id=#{id}
